#!/usr/bin/env python3
"""PreToolUse(Edit|Write|NotebookEdit): generated files, lockfiles and secrets are never edited by hand (exit 2).

A generated file is one under the default generated paths, or any file whose first line is devkit's generated
marker (so a project that moves its generated directory is still covered). An edit that writes a name the guards
read (guard_bash.OWNER_ENV) into a Claude Code settings file is refused too: its `env` block reaches every hook (#191).
"""

import json
import re
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
from guard_bash import OWNER_ENV

RULES = [
    (r"(^|/)docs/generated/", "docs/generated/ is generated: change the source, then `uv run dev docs`."),
    (r"(^|/)docs/research/INDEX\.md$", "INDEX.md is generated from the notes: edit the note, then `uv run dev docs`."),
    (r"(^|/)uv\.lock$", "uv.lock is written by uv: `uv add` / `uv lock`."),
    (r"(^|/)\.env(\.[\w-]+)?$(?<!\.example)", "Secrets stay out of agent hands: the owner edits .env."),
    (r"(^|/)devkit/quota_cap$", "the quota cap is the owner's: `! uv run dev quota-cap <pct>`, never an agent."),
]
MARKER = "<!-- Generated by `uv run dev docs`."
SETTINGS = re.compile(r"(^|[/\\])\.claude[/\\]settings(\.[\w-]+)?\.json$")
OVERRIDE = (
    "{name} is read by the guards and is the owner's alone: it counts only from the shell that starts Claude Code, "
    "never from a settings file's env block. Ask the owner."
)


def plain(text: str) -> str:
    """JSON \\u escapes decoded, so `DEVKIT\\u005fLIT_RAW` reads as the name it is."""
    return re.sub(r"\\u([0-9a-fA-F]{4})", lambda m: chr(int(m.group(1), 16)), text)


def after(path: str, inp: dict) -> tuple[str, str]:
    """The file's text before and after the call. An Edit whose old text is missing fails in the tool, so the text it
    would write stands in for the result."""
    try:
        with open(path, encoding="utf-8", errors="replace") as f:
            before = f.read()
    except OSError:
        before = ""
    if isinstance(inp.get("content"), str):  # Write
        return before, inp["content"]
    edits = inp.get("edits") if isinstance(inp.get("edits"), list) else [inp]  # MultiEdit, or one Edit
    text = before
    for e in edits:
        old, new = (e.get("old_string"), e.get("new_string")) if isinstance(e, dict) else (None, None)
        if not isinstance(new, str):
            continue
        if isinstance(old, str) and old and old in text:
            text = text.replace(old, new, -1 if e.get("replace_all") else 1)
        else:
            text += "\n" + new
    return before, text


def override(path: str, inp: dict) -> str | None:
    """The first guard-read name the call adds to the file (removing one is fine)."""
    before, now = (plain(t) for t in after(path, inp))
    return next((name for name in OWNER_ENV if now.count(name) > before.count(name)), None)


def generated(path: str) -> bool:
    try:
        with open(path, encoding="utf-8", errors="replace") as f:
            return f.readline().startswith(MARKER)
    except OSError:
        return False


def main() -> int:
    try:
        data = json.load(sys.stdin)
    except json.JSONDecodeError:
        return 0
    if not isinstance(data, dict) or not isinstance(data.get("tool_input"), dict):
        return 0
    inp = data["tool_input"]
    path = inp.get("file_path") or inp.get("notebook_path") or ""
    if not isinstance(path, str):
        return 0
    if SETTINGS.search(path) and (name := override(path, inp)):
        print(f"Blocked by project rule: {OVERRIDE.format(name=name)}", file=sys.stderr)
        return 2
    for pattern, why in RULES:
        if re.search(pattern, path):
            print(f"Blocked by project rule: {why}", file=sys.stderr)
            return 2
    if generated(path):
        print(
            "Blocked by project rule: the file is generated: change its source, then `uv run dev docs`.",
            file=sys.stderr,
        )
        return 2
    return 0


if __name__ == "__main__":
    sys.exit(main())
